{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "Rifapentine, a very close analogue of the query differing only in the piperazine N-substituent (cyclopentyl vs methyl), has an absolute oral bioavailability of 70% in healthy adult volunteers after a 600 mg tablet dose.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "The FDA label reports rifapentine as 70% bioavailable in humans, directly supporting high oral bioavailability for this rifamycin class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Human volunteer studies report rifapentine oral bioavailability of 70%, reinforcing the high-absorption phenotype of the closest structural analogue.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Rifaximin, a less similar rifamycin derivative with a modified heterocyclic system, has less than 0.4% oral bioavailability in healthy volunteers; this contradictory low-F evidence has limited transferability to the query because of substantial structural differences.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is rifampicin, and its closest retrieved analogue rifapentine (Morgan similarity 0.87) has a measured absolute oral bioavailability of 70% in humans, well above the 20% threshold. The structural difference is limited to the piperazine N-substituent, so the high-F phenotype transfers strongly. Less similar rifamycin derivatives with low bioavailability are outweighed by the close analogue evidence.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself was provided; the prediction relies on the very close analogue rifapentine.",
    "The effect of the methyl-versus-cyclopentyl piperazine substitution on absorption is not directly quantified, though both are lipophilic tertiary amine substituents expected to preserve high permeability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

